function makeEl(tag) {
  const listeners = {};
  const el = {
    tag, children: [], textContent: "", value: "", className: "", dataset: {},
    appendChild(c) { this.children.push(c); return c; },
    addEventListener(type, fn) { (listeners[type] ||= []).push(fn); },
    fire(type, event = {}) { for (const fn of listeners[type] || []) fn(event); },
