  return el;
}

function session(storage) {
  const els = {};
  for (const id of ["filter", "tasks", "title", "add"]) els[id] = makeEl(id);
  els.filter.value = "all";
  const doc = {
    getElementById: id => els[id],
    createElement: tag => makeEl(tag),
    addEventListener(type, fn) { if (type === "DOMContentLoaded") this.ready = fn; },
  };
  const ls = {
    getItem: k => (k in storage ? storage[k] : null),
    setItem: (k, v) => { storage[k] = String(v); },
  };
  const ctx = { document: doc, localStorage: ls, JSON, Math, Number, String };
  vm.createContext(ctx);
  vm.runInContext(appSrc, ctx);
  doc.ready();
  return { els, fire: (id, type, ev) => els[id].fire(type, ev) };
}
const titles = els => els.tasks.children.map(li => li.textContent + (li.className ? "[" + li.className + "]" : ""));

const storage = {};
let s = session(storage);
s.els.title.value = "write"; s.fire("add", "click");
s.els.title.value = "write"; s.fire("add", "click");
s.els.title.value = "review"; s.fire("add", "click");
const ids = s.els.tasks.children.map(li => li.dataset.id);
