// complete only the first "write"
s.fire("tasks", "click", { target: s.els.tasks.children[0] });
assert.deepStrictEqual(titles(s.els), ["write[done]", "write[]", "review[]"]);

// reload: new session over same storage
s = session(storage);
assert.deepStrictEqual(titles(s.els), ["write[done]", "write[]", "review[]"], "state after reload");

// filter persists across reload
s.els.filter.value = "open"; s.fire("filter", "change");
s = session(storage);
assert.strictEqual(s.els.filter.value, "open");
assert.deepStrictEqual(titles(s.els), ["write[]", "review[]"], "open filter after reload");

// add after reload keeps numbering collision-free
s.els.filter.value = "all"; s.fire("filter", "change");
s.els.title.value = "ship"; s.fire("add", "click");
s = session(storage);
assert.deepStrictEqual(titles(s.els), ["write[done]", "write[]", "review[]", "ship[]"]);
console.log("reload checks passed");
