    if \(!event\.target\.dataset\.id\) return;
    tasks = complete\(tasks, event\.target\.dataset\.id\);
    save\(tasks\);
    render\(tasks, selection\);
  \}\);
  render\(tasks, selection\);
\}

document\.addEventListener\("DOMContentLoaded", start\);
